//! Generated by steelix from `app.py` and the modules of its project.

#![allow(non_snake_case, unused_variables, unused_assignments)]
#![allow(clippy::never_loop, clippy::approx_constant, clippy::if_same_then_else)]
#![allow(clippy::too_many_arguments, clippy::doc_lazy_continuation)]
#![allow(
    clippy::while_immutable_condition,
    clippy::eq_op,
    clippy::nonminimal_bool
)]
#![allow(clippy::overly_complex_bool_expr, clippy::collapsible_if)]
#![allow(clippy::module_inception)]

mod app;
mod json;
mod ns;

use steelix_runtime::NativeModule;

/// The project's modules: `import` runs their transpiled code instead of
/// their Python source.
const MODULES: &[NativeModule] = &[
    NativeModule::module("json.shadowed", json::shadowed::exec_module),
    NativeModule::module("ns.deep.leaf", ns::deep::leaf::exec_module),
    NativeModule::module("ns.helper", ns::helper::exec_module),
    NativeModule::package("ns.pkg", ns::pkg::exec_module),
    NativeModule::module("ns.pkg.inner", ns::pkg::inner::exec_module),
    NativeModule::module("ns.tool", ns::tool::exec_module),
];

fn main() -> std::process::ExitCode {
    let script = steelix_runtime::script!("app.py");
    steelix_runtime::embed::run_project(&script, MODULES, app::exec_module)
}
